# GENERATED by tools/translate.py from the async/await original. Do not edit.
"""Scoped trigger bindings: cases not covered by the TriggerTest.java port.

Expected behavior follows the Java implementation (Trigger.poll / clearStaleBindings and
Scheduler.cancelStaleBindings): edge bindings fire only on a signal change of the same
trigger object, a new trigger's first poll counts as an edge, and the narrowest scope
(command > opmode > robot mode > global) owns both the binding and the trigger's lifetime.
"""

import gc
import weakref

from commands3._common.api import Command, RobotMode, Trigger
from commands3._common.binding import ForCommand, ForOpmode
from commands3._frontends.greenlets import Coroutine, co

from .helpers import Ref


def park(name="Command"):
    return Command.no_requirements(co.park).named(name)


def collected(ref) -> bool:
    for _ in range(5):
        if ref() is None:
            return True
        gc.collect()
    return ref() is None


def _outer_binding(scheduler, signal, inner, binding="while_true", trigger_ref=None):
    def outer_body():
        t = Trigger(scheduler, signal.get)
        if trigger_ref is not None:
            trigger_ref.set(t)
        getattr(t, binding)(inner)
        co.park()

    return Command.no_requirements(outer_body).named("Outer")


# ------------------------------------------------------------------ command scope -------
def test_while_true_bound_in_command_is_canceled_with_the_command(scheduler):
    signal = Ref(False)
    inner = park("Inner")
    outer = _outer_binding(scheduler, signal, inner)
    scheduler.schedule(outer)
    scheduler.run()
    signal.set(True)
    scheduler.run()
    assert scheduler.is_running(inner)
    assert scheduler.get_parent_of(inner) is outer, "command-scoped bindings fork children"

    scheduler.cancel(outer)
    assert not scheduler.is_running(inner)
    scheduler.run()
    assert not scheduler.is_running(inner), "the signal is still high, but the scope is gone"


def test_while_true_bound_in_command_is_canceled_when_the_command_completes(scheduler):
    signal, finish = Ref(True), Ref(False)
    inner = park("Inner")

    def outer_body():
        Trigger(scheduler, signal.get).while_true(inner)
        co.wait_until(finish.get)

    outer = Command.no_requirements(outer_body).named("Outer")
    scheduler.schedule(outer)
    scheduler.run()
    scheduler.run()
    assert scheduler.is_running(inner)
    finish.set(True)
    scheduler.run()
    assert not scheduler.is_running(outer)
    assert not scheduler.is_running(inner)


def test_command_scope_wins_over_opmode(scheduler, robot):
    robot.opmode_id, robot.opmode_name = 7, "Opmode 7"
    signal, trigger_ref = Ref(True), Ref()
    inner = park("Inner")
    outer = _outer_binding(scheduler, signal, inner, trigger_ref=trigger_ref)
    scheduler.schedule(outer)
    scheduler.run()
    scheduler.run()
    assert scheduler.is_running(inner)

    trigger = trigger_ref.get()
    binding = trigger._bindings[next(iter(trigger._bindings))][0]
    assert binding.scope == ForCommand(scheduler, outer)
    assert trigger._lifetime_scope == ForCommand(scheduler, outer)

    # The opmode is still active, but the command scope ends with the outer command.
    scheduler.cancel(outer)
    scheduler.run()
    assert not scheduler.is_running(inner)


def test_command_scoped_bindings_end_with_the_opmode_that_owns_the_command(scheduler, robot):
    robot.opmode_id, robot.opmode_name = 7, "Opmode 7"
    signal = Ref(True)
    inner = park("Inner")
    outer = _outer_binding(scheduler, signal, inner)
    scheduler.schedule(outer)  # opmode-scoped
    scheduler.run()
    scheduler.run()
    assert scheduler.is_running(outer) and scheduler.is_running(inner)

    robot.opmode_id, robot.opmode_name = 8, "Opmode 8"
    scheduler.run()
    assert not scheduler.is_running(outer)
    assert not scheduler.is_running(inner)


# ------------------------------------------------------------------ opmode scope --------
def test_switching_directly_between_opmodes_cancels_old_bindings(scheduler, robot):
    robot.opmode_id, robot.opmode_name = 1, "Opmode 1"
    signal = Ref(True)
    old_cmd = park("Opmode 1 command")
    old_trigger = Trigger(scheduler, signal.get)
    old_trigger.while_true(old_cmd)
    scheduler.run()
    assert scheduler.is_running(old_cmd)
    assert old_trigger._lifetime_scope == ForOpmode(1)

    robot.opmode_id, robot.opmode_name = 2, "Opmode 2"
    scheduler.run()
    assert not scheduler.is_running(old_cmd)
    ref = weakref.ref(old_trigger)
    del old_trigger
    assert collected(ref), "a trigger created in opmode 1 is unbound once opmode 1 ends"

    new_cmd = park("Opmode 2 command")
    Trigger(scheduler, signal.get).while_true(new_cmd)
    scheduler.run()
    assert scheduler.is_running(new_cmd), "a new trigger's first poll is a rising edge"
    scheduler.run()
    assert scheduler.is_running(new_cmd)


def test_command_reused_by_a_trigger_in_the_next_opmode_keeps_running(scheduler, robot):
    robot.opmode_id, robot.opmode_name = 1, "Opmode 1"
    signal = Ref(True)
    cmd = park("Shared")
    Trigger(scheduler, signal.get).while_true(cmd)
    scheduler.run()
    assert scheduler.is_running(cmd)

    robot.opmode_id, robot.opmode_name = 2, "Opmode 2"
    trigger = Trigger(scheduler, signal.get)
    trigger.while_true(cmd)
    scheduler.run()
    assert scheduler.is_running(cmd), "rescheduled by the opmode 2 trigger"
    for _ in range(3):
        scheduler.run()
        assert scheduler.is_running(cmd), "the stale opmode 1 binding must not cancel it"
    signal.set(False)
    scheduler.run()
    assert not scheduler.is_running(cmd)


def test_returning_to_an_opmode_does_not_revive_its_old_triggers(scheduler, robot):
    robot.opmode_id, robot.opmode_name = 1, "Opmode 1"
    signal = Ref(False)
    cmd = park()
    Trigger(scheduler, signal.get).on_true(cmd)
    scheduler.run()
    robot.opmode_id, robot.opmode_name = 2, "Opmode 2"
    scheduler.run()
    gc.collect()
    robot.opmode_id, robot.opmode_name = 1, "Opmode 1"
    scheduler.run()
    signal.set(True)
    scheduler.run()
    assert not scheduler.is_running(cmd)


# --------------------------------------------------------- signal held across a change ---
def test_held_signal_across_mode_change_does_not_refire_edge_bindings(scheduler, robot):
    robot.robot_mode = RobotMode.TELEOPERATED
    signal = Ref(True)
    trigger = Trigger(scheduler, signal.get)  # robot-mode scope: the trigger lives globally
    teleop_cmd = park("Teleop")
    trigger.on_true(teleop_cmd)
    scheduler.run()
    assert scheduler.is_running(teleop_cmd)

    robot.robot_mode = RobotMode.AUTONOMOUS
    auto_on_true, auto_while_true, auto_if_true = park("on_true"), park("while_true"), park("if_true")
    trigger.on_true(auto_on_true)
    trigger.while_true(auto_while_true)
    trigger.if_true(auto_if_true)
    scheduler.run()
    assert not scheduler.is_running(teleop_cmd), "its robot-mode binding went stale"
    assert not scheduler.is_running(auto_on_true), "no rising edge: the signal never went low"
    assert not scheduler.is_running(auto_while_true), "no rising edge: the signal never went low"
    assert scheduler.is_running(auto_if_true), "level bindings schedule on every high poll"

    signal.set(False)
    scheduler.run()
    signal.set(True)
    scheduler.run()
    assert scheduler.is_running(auto_on_true)
    assert scheduler.is_running(auto_while_true)


def test_held_signal_fires_a_trigger_created_in_the_new_mode(scheduler, robot):
    robot.robot_mode = RobotMode.TELEOPERATED
    signal = Ref(True)
    Trigger(scheduler, signal.get).on_true(park("Teleop"))
    scheduler.run()

    robot.robot_mode = RobotMode.AUTONOMOUS
    auto_cmd = park("Auto")
    Trigger(scheduler, signal.get).on_true(auto_cmd)
    scheduler.run()
    assert scheduler.is_running(auto_cmd), "a new trigger has no previous signal"
